using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using WoWProbe;
class CampaignSettingsTests
{
    static int passed,failed;static void Test(string name,Action a){try{a();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}static void Assert(bool b){if(!b)throw new Exception("assertion failed");}static void Reject(Action a){try{a();}catch(ArgumentException){return;}catch(FormatException){return;}catch(InvalidOperationException){return;}throw new Exception("unsafe settings accepted");}
    static CampaignPlan Plan(){var f=new RouteDocument{RouteId="farm",Name="Farm",MapId=900001,MapMode=2,Zone="Simulation only",Points=new List<Waypoint>{new Waypoint{X=.5,Y=.5},new Waypoint{X=.52,Y=.5},new Waypoint{X=.52,Y=.52},new Waypoint{X=.5,Y=.5}}};var c=f.Clone();c.RouteId="corpse";c.RouteType="corpse_run";c.Points=new List<Waypoint>{new Waypoint{X=.48,Y=.5},new Waypoint{X=.5,Y=.5}};var v=f.Clone();v.RouteId="vendor";v.RouteType="vendor_return";v.Points=new List<Waypoint>{new Waypoint{X=.5,Y=.5},new Waypoint{X=.46,Y=.5}};return new CampaignPlan{FarmRoute=f,CorpseRoute=c,VendorRoute=v,Settings=new CampaignSettings(),Battle=new BattleProfile{Calibration=new NavigationCalibration{MapId=f.MapId,MapMode=f.MapMode,Zone=f.Zone},Targets=new List<BattleTarget>{new BattleTarget{Name="Mob",NameHash=TargetCatalog.HashName("Mob")},new BattleTarget{Name="Vendor",NameHash=TargetCatalog.HashName("Vendor"),Kind="npc"}}}};}
    static int Main(){string dir=Path.Combine(Path.GetTempPath(),"wow-campaign-settings-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string path=Path.Combine(dir,"settings.json");
        Test("defaults require explicit live confirmation and preserve gray-only policy",delegate{var s=new CampaignSettings();s.Validate();Assert(!s.BindingsConfirmed&&!s.UiConfirmed&&!s.AutoResumeConfirmed&&s.MaxSaleQuality==0&&!s.AutoCleanOnly&&s.NpcSelectKey==0x75);});
        Test("strict settings roundtrip resets all live confirmations",delegate{var s=new CampaignSettings{BindingsConfirmed=true,UiConfirmed=true,AutoResumeConfirmed=true,ProtectedItemIds=new List<uint>{123,456}};CampaignSettingsStore.Save(path,s);var r=CampaignSettingsStore.Load(path);Assert(!r.BindingsConfirmed&&!r.UiConfirmed&&!r.AutoResumeConfirmed&&r.ProtectedItemIds.Count==2&&s.BindingsConfirmed);});
        Test("settings clone isolates protected item collection",delegate{var s=new CampaignSettings{ProtectedItemIds=new List<uint>{1}};var c=s.Clone();c.ProtectedItemIds.Add(2);Assert(s.ProtectedItemIds.Count==1);});
        Test("all key numeric limits and unknown types are rejected",delegate{foreach(int n in new[]{-1,2,7}){var s=new CampaignSettings{MaxSaleQuality=n};Reject(s.Validate);}Reject(new CampaignSettings{JoinTolerance=Double.NaN}.Validate);Reject(new CampaignSettings{CorpseTolerance=.03}.Validate);Reject(new CampaignSettings{DeathConfirmFrames=1}.Validate);Reject(new CampaignSettings{NpcSelectKey=0x57}.Validate);Reject(new CampaignSettings{ClientWidth=0}.Validate);Reject(new CampaignSettings{MinimumFreeSlots=0}.Validate);Reject(new CampaignSettings{SaleLimit=10000}.Validate);});
        Test("protected IDs must be unique valid bounded values",delegate{Reject(new CampaignSettings{ProtectedItemIds=new List<uint>{0}}.Validate);Reject(new CampaignSettings{ProtectedItemIds=new List<uint>{1,1}}.Validate);Reject(new CampaignSettings{ProtectedItemIds=null}.Validate);});
        Test("invalid replacement retains last good settings",delegate{CampaignSettingsStore.Save(path,new CampaignSettings());var before=File.ReadAllBytes(path);Reject(delegate{CampaignSettingsStore.Save(path,new CampaignSettings{MaxSaleQuality=3});});Assert(Convert.ToBase64String(before)==Convert.ToBase64String(File.ReadAllBytes(path)));});
        Test("missing extra duplicate and string typed fields are rejected",delegate{CampaignSettingsStore.Save(path,new CampaignSettings());var json=File.ReadAllText(path,Encoding.UTF8);foreach(string bad in new[]{json.Replace("\"schema_version\":1","\"schema_version\":\"1\""),json.Replace("\"schema_version\":1,",""),json.Replace("\"schema_version\":1","\"schema_version\":1,\"extra\":1"),json.Replace("\"schema_version\":1","\"schema_version\":1,\"schema_version\":1")}){File.WriteAllText(path,bad,new UTF8Encoding(false));Reject(delegate{CampaignSettingsStore.Load(path);});}});
        Test("plan validates three route roles map links and NPC identity",delegate{var p=Plan();p.Validate();p.VendorRoute.MapId++;Reject(p.Validate);p=Plan();p.CorpseRoute.RouteType="farm";Reject(p.Validate);p=Plan();p.VendorRoute.Points[0].X=.4;Reject(p.Validate);p=Plan();p.Battle.Targets.RemoveAt(1);Reject(p.Validate);});
        Test("disabled interruption modes need no extra routes",delegate{var p=Plan();p.Settings.EnableRecovery=p.Settings.EnableVendor=false;p.CorpseRoute=p.VendorRoute=null;p.Battle.Targets.RemoveAt(1);p.Validate();});
        Test("plan cannot inject waypoint interactions or forbid required return",delegate{var p=Plan();p.VendorRoute.AllowReverse=false;Reject(p.Validate);p=Plan();p.FarmRoute.Points[1].Action="interact";Reject(p.Validate);});
        Test("recovery requires a reversible farm route even when vendor travel is disabled",delegate{var p=Plan();p.Settings.EnableVendor=false;p.FarmRoute.AllowReverse=false;Reject(p.Validate);});
        Test("full plan clone and fingerprint bind behavior and mutable data",delegate{var p=Plan();var c=p.Clone();Assert(p.Fingerprint()==c.Fingerprint());c.Settings.ProtectedItemIds.Add(77);Assert(p.Fingerprint()!=c.Fingerprint()&&p.Settings.ProtectedItemIds.Count==0);c=p.Clone();c.VendorRoute.Points[1].X=.45;Assert(p.Fingerprint()!=c.Fingerprint());c=p.Clone();c.Battle.SkillSequence="14111";Assert(p.Fingerprint()!=c.Fingerprint());});
        Test("start index direction and calibration remain explicit",delegate{var p=Plan();p.StartIndex=p.FarmRoute.Points.Count;Reject(p.Validate);p=Plan();p.Battle.Calibration.MapMode=1;Reject(p.Validate);p=Plan();p.FarmReverse=true;p.Validate();});
        Console.WriteLine("Campaign settings tests: "+passed+" passed, "+failed+" failed");return failed==0?0:1;
    }
}
